use std::cell::RefCell;
use std::rc::Rc;
use std::collections::HashMap;

fn copy_chain(head: Option<Rc<RefCell<RandomListNode>>>) -> Option<Rc<RefCell<RandomListNode>>> {
    // 1. The originals in order, and each one's position, keyed by address.
    let mut originals = Vec::new();
    let mut cur = head;
    while let Some(node) = cur {
        cur = node.borrow().next.clone();
        originals.push(node);
    }
    let position: HashMap<_, _> = originals.iter().enumerate().map(|(i, n)| (Rc::as_ptr(n), i)).collect();
    // 2. One copy per original, then wire each copy as its original is wired.
    let copies: Vec<_> =
        originals.iter().map(|n| Rc::new(RefCell::new(RandomListNode::new(n.borrow().val)))).collect();
    for (i, original) in originals.iter().enumerate() {
        let mut copy = copies[i].borrow_mut();
        copy.next = copies.get(i + 1).cloned();
        copy.random = original.borrow().random.as_ref().map(|r| Rc::clone(&copies[position[&Rc::as_ptr(r)]]));
    }
    copies.into_iter().next()
}

use std::cell::RefCell;
use std::rc::Rc;

fn copy_chain(head: Option<Rc<RefCell<RandomListNode>>>) -> Option<Rc<RefCell<RandomListNode>>> {
    // Every original has its copy woven in right after it during steps 1-3, so
    // `next` of an original is always Some(copy): the unwraps can't fail.
    // 1. Weave a copy in after each original: A -> A' -> B -> B' -> ...
    let mut cur = head.clone();
    while let Some(original) = cur {
        let copy = Rc::new(RefCell::new(RandomListNode::new(original.borrow().val)));
        copy.borrow_mut().next = original.borrow_mut().next.take();
        cur = copy.borrow().next.clone();
        original.borrow_mut().next = Some(copy);
    }
    // 2. A copy's random is the node right after its original's random.
    let mut cur = head.clone();
    while let Some(original) = cur {
        let copy = original.borrow().next.clone().unwrap();
        let random = original.borrow().random.as_ref().map(|r| r.borrow().next.clone().unwrap());
        copy.borrow_mut().random = random;
        cur = copy.borrow().next.clone();
    }
    // 3. Unweave the two chains, restoring the original.
    let new_head = head.as_ref().map(|h| h.borrow().next.clone().unwrap());
    let mut cur = head;
    while let Some(original) = cur {
        let copy = original.borrow().next.clone().unwrap();
        let next_original = copy.borrow().next.clone();
        copy.borrow_mut().next = next_original.as_ref().map(|n| n.borrow().next.clone().unwrap());
        original.borrow_mut().next = next_original.clone();
        cur = next_original;
    }
    new_head
}
